-- ---- functions the tables need (triggers, checks); bodies are not checked until tables exist
-- update_updated_at_column
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$;

-- catalog_bump_version
CREATE OR REPLACE FUNCTION public.catalog_bump_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.version := 1;
    ELSE
        NEW.version := OLD.version + 1;
    END IF;
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$function$;

-- normalise_environment_url
CREATE OR REPLACE FUNCTION public.normalise_environment_url(p_url text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    v_url TEXT;
    v_scheme TEXT;
    v_host TEXT;
BEGIN
    IF p_url IS NULL THEN
        RETURN NULL;
    END IF;

    v_url := LOWER(TRIM(p_url));

    -- Require an explicit scheme; without one we cannot tell host from path.
    IF POSITION('://' IN v_url) = 0 THEN
        RETURN NULL;
    END IF;

    v_scheme := SPLIT_PART(v_url, '://', 1);
    -- Everything after the FIRST '://' (a path may legally contain another).
    v_host := SUBSTRING(v_url FROM POSITION('://' IN v_url) + 3);

    -- Strip userinfo (everything up to and including the last '@' before the
    -- first '/'), then path/query/fragment, then port.
    v_host := REGEXP_REPLACE(v_host, '^[^/]*@', '');
    v_host := SPLIT_PART(v_host, '/', 1);
    v_host := SPLIT_PART(v_host, '?', 1);
    v_host := SPLIT_PART(v_host, '#', 1);
    v_host := SPLIT_PART(v_host, ':', 1);

    IF v_scheme = '' OR v_host = '' THEN
        RETURN NULL;
    END IF;

    RETURN v_scheme || '://' || v_host;
END;
$function$;

-- current_week_start
CREATE OR REPLACE FUNCTION public.current_week_start()
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
    RETURN DATE_TRUNC('week', NOW())::DATE;
END;
$function$;

-- get_telemetry_stats
CREATE OR REPLACE FUNCTION public.get_telemetry_stats(p_user_id uuid)
 RETURNS TABLE(period text, total_batch_runs bigint, total_batch_records bigint, total_api_calls bigint, total_execution_time_ms bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    -- Weekly stats (Monday-based week)
    RETURN QUERY
    SELECT
        'weekly'::TEXT AS period,
        COALESCE(SUM(te.batch_runs), 0)::BIGINT AS total_batch_runs,
        COALESCE(SUM(te.batch_records), 0)::BIGINT AS total_batch_records,
        COALESCE(SUM(te.api_calls), 0)::BIGINT AS total_api_calls,
        COALESCE(SUM(te.execution_time_ms), 0)::BIGINT AS total_execution_time_ms
    FROM telemetry_events te
    WHERE te.user_id = p_user_id
      AND te.event_date >= DATE_TRUNC('week', NOW())::DATE;

    -- All-time stats
    RETURN QUERY
    SELECT
        'alltime'::TEXT AS period,
        COALESCE(SUM(te.batch_runs), 0)::BIGINT AS total_batch_runs,
        COALESCE(SUM(te.batch_records), 0)::BIGINT AS total_batch_records,
        COALESCE(SUM(te.api_calls), 0)::BIGINT AS total_api_calls,
        COALESCE(SUM(te.execution_time_ms), 0)::BIGINT AS total_execution_time_ms
    FROM telemetry_events te
    WHERE te.user_id = p_user_id;
END;
$function$;

-- upsert_telemetry_events
CREATE OR REPLACE FUNCTION public.upsert_telemetry_events(p_events jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_event JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    FOR v_event IN SELECT * FROM jsonb_array_elements(p_events)
    LOOP
        INSERT INTO telemetry_events (
            user_id,
            event_date,
            environment_base_url,
            api_calls,
            batch_runs,
            batch_records,
            batch_successes,
            batch_failures,
            export_records,
            import_records,
            execution_time_ms,
            features_used,
            extension_version,
            vscode_version,
            os_platform
        ) VALUES (
            v_user_id,
            (v_event->>'event_date')::DATE,
            v_event->>'environment_base_url',
            COALESCE((v_event->>'api_calls')::INTEGER, 0),
            COALESCE((v_event->>'batch_runs')::INTEGER, 0),
            COALESCE((v_event->>'batch_records')::INTEGER, 0),
            COALESCE((v_event->>'batch_successes')::INTEGER, 0),
            COALESCE((v_event->>'batch_failures')::INTEGER, 0),
            COALESCE((v_event->>'export_records')::INTEGER, 0),
            COALESCE((v_event->>'import_records')::INTEGER, 0),
            COALESCE((v_event->>'execution_time_ms')::BIGINT, 0),
            COALESCE(v_event->'features_used', '{}'::JSONB),
            v_event->>'extension_version',
            v_event->>'vscode_version',
            v_event->>'os_platform'
        )
        ON CONFLICT (user_id, event_date, environment_base_url)
        DO UPDATE SET
            api_calls         = telemetry_events.api_calls         + EXCLUDED.api_calls,
            batch_runs        = telemetry_events.batch_runs        + EXCLUDED.batch_runs,
            batch_records     = telemetry_events.batch_records     + EXCLUDED.batch_records,
            batch_successes   = telemetry_events.batch_successes   + EXCLUDED.batch_successes,
            batch_failures    = telemetry_events.batch_failures    + EXCLUDED.batch_failures,
            export_records    = telemetry_events.export_records    + EXCLUDED.export_records,
            import_records    = telemetry_events.import_records    + EXCLUDED.import_records,
            execution_time_ms = telemetry_events.execution_time_ms + EXCLUDED.execution_time_ms,
            features_used     = telemetry_events.features_used || EXCLUDED.features_used,
            extension_version = EXCLUDED.extension_version,
            vscode_version    = EXCLUDED.vscode_version,
            os_platform       = EXCLUDED.os_platform,
            updated_at        = NOW();
    END LOOP;
END;
$function$;

-- upsert_telemetry_endpoint_usage
CREATE OR REPLACE FUNCTION public.upsert_telemetry_endpoint_usage(p_rows jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_row JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;
    IF jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) > 500 THEN
        RAISE EXCEPTION 'p_rows must be an array of at most 500 rows' USING ERRCODE = '22023';
    END IF;

    FOR v_row IN SELECT * FROM jsonb_array_elements(p_rows)
    LOOP
        INSERT INTO public.telemetry_endpoint_usage (
            user_id, event_date, environment_base_url, method, path_template,
            calls, failures, execution_time_ms, extension_version
        ) VALUES (
            v_user_id,
            (v_row->>'event_date')::DATE,
            v_row->>'environment_base_url',
            v_row->>'method',
            v_row->>'path_template',
            GREATEST(COALESCE((v_row->>'calls')::INTEGER, 0), 0),
            GREATEST(COALESCE((v_row->>'failures')::INTEGER, 0), 0),
            GREATEST(COALESCE((v_row->>'execution_time_ms')::BIGINT, 0), 0),
            v_row->>'extension_version'
        )
        ON CONFLICT (user_id, event_date, environment_base_url, method, path_template)
        DO UPDATE SET
            calls             = telemetry_endpoint_usage.calls + EXCLUDED.calls,
            failures          = telemetry_endpoint_usage.failures + EXCLUDED.failures,
            execution_time_ms = telemetry_endpoint_usage.execution_time_ms + EXCLUDED.execution_time_ms,
            extension_version = EXCLUDED.extension_version,
            updated_at        = NOW();
    END LOOP;
END;
$function$;

-- catalog_next_sequence
CREATE OR REPLACE FUNCTION public.catalog_next_sequence(p_endpoint_id text, p_array_path text DEFAULT ''::text, p_count integer DEFAULT 1, p_after bigint DEFAULT 0)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE
    reserved BIGINT;
BEGIN
    IF p_count IS NULL OR p_count < 1 OR p_count > 10000 THEN
        RAISE EXCEPTION 'p_count must be between 1 and 10000' USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.catalog_sequences (owner_user_id, endpoint_id, array_path, value)
    VALUES (auth.uid(), p_endpoint_id, COALESCE(p_array_path, ''), GREATEST(COALESCE(p_after, 0), 0) + p_count)
    ON CONFLICT (owner_user_id, endpoint_id, array_path)
    DO UPDATE SET value = GREATEST(public.catalog_sequences.value, COALESCE(p_after, 0)) + p_count
    RETURNING value INTO reserved;
    RETURN reserved;
END;
$function$;

-- user_settings_set
CREATE OR REPLACE FUNCTION public.user_settings_set(p_key text, p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_settings JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;
    IF p_key IS NULL OR p_key !~ '^[A-Za-z][A-Za-z0-9_-]*(\.[A-Za-z0-9_-]+){1,5}$' OR char_length(p_key) > 120 THEN
        RAISE EXCEPTION 'Invalid setting name' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.user_settings AS s (user_id, settings)
    VALUES (v_user_id, CASE WHEN p_value IS NULL OR p_value = 'null'::JSONB THEN '{}'::JSONB ELSE jsonb_build_object(p_key, p_value) END)
    ON CONFLICT (user_id) DO UPDATE SET
        settings = CASE
            WHEN p_value IS NULL OR p_value = 'null'::JSONB THEN s.settings - p_key
            ELSE s.settings || jsonb_build_object(p_key, p_value)
        END,
        updated_at = NOW()
    RETURNING settings INTO v_settings;
    RETURN v_settings;
END;
$function$;

-- catalog_return_sequence
CREATE OR REPLACE FUNCTION public.catalog_return_sequence(p_endpoint_id text, p_array_path text, p_reserved_to bigint, p_used_to bigint)
 RETURNS boolean
 LANGUAGE sql
AS $function$
    WITH returned AS (
        UPDATE public.catalog_sequences
        SET value = p_used_to
        WHERE owner_user_id = auth.uid()
          AND endpoint_id = p_endpoint_id
          AND array_path = COALESCE(p_array_path, '')
          AND value = p_reserved_to
          AND p_used_to >= 0
          AND p_used_to < p_reserved_to
        RETURNING 1
    )
    SELECT EXISTS (SELECT 1 FROM returned);
$function$;

-- catalog_reset_sequence
CREATE OR REPLACE FUNCTION public.catalog_reset_sequence(p_endpoint_id text, p_array_path text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE sql
AS $function$
    UPDATE public.catalog_sequences
    SET value = 0
    WHERE owner_user_id = auth.uid()
      AND endpoint_id = p_endpoint_id
      AND CASE
            WHEN p_array_path IS NULL THEN array_path = ''
            WHEN p_array_path = '*' THEN array_path <> ''
            ELSE array_path = p_array_path
          END;
$function$;

-- catalog_environment_has_secret_values
CREATE OR REPLACE FUNCTION public.catalog_environment_has_secret_values(item jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
    SELECT EXISTS (
        -- A header marked secret, with a value
        SELECT 1
        FROM jsonb_each(CASE WHEN jsonb_typeof(item->'headers') = 'object' THEN item->'headers' ELSE '{}'::jsonb END) AS h(name, header)
        WHERE jsonb_typeof(header) = 'object'
          AND header->'secret' = 'true'::jsonb
          AND COALESCE(header->>'value', '') <> ''
    ) OR EXISTS (
        -- A variable named secret, with a value
        SELECT 1
        FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(item->'secretVariables') = 'array' THEN item->'secretVariables' ELSE '[]'::jsonb END) AS v(name)
        WHERE COALESCE(item->'variables'->>v.name, '') <> ''
    );
$function$;

