REVOKE ALL ON FUNCTION public.increment_usage(p_week_start date, p_batch_delta integer, p_export_delta integer, p_import_delta integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.increment_usage(p_week_start date, p_batch_delta integer, p_export_delta integer, p_import_delta integer) TO authenticated, service_role;
